#!/usr/bin/env python3
"""Generate four Chapter 09 scene-specific PNG illustrations for Artico.

The embedded source is zlib-compressed to preserve artwork in the repository
without relying on temporary image URLs or external image services.
"""
import base64
import zlib
_ARTWORK_SOURCE = ""
exec(compile(zlib.decompress(base64.b64decode(_ARTWORK_SOURCE)), __file__, "exec"))
